    organicControl: 'Foliar spray of fermented cow urine and ginger-garlic extract. Apply fermented buttermilk or wood ash dusting during early morning dew.',
    organicControlKn: 'ಗೋಮೂತ್ರ ಮತ್ತು ಶುಂಠಿ-ಬೆಳ್ಳುಳ್ಳಿ ಕಷಾಯ ಸಿಂಪಡಿಸಿ. ಮುಂಜಾನೆ ಇಬ್ಬನಿ ಇರುವಾಗ ಬೂದಿ ಉದುರಿಸಿ.',
    organicControlTa: 'கோமியம் மற்றும் இஞ்சி பூண்டு கரைசல் தெளிக்கவும். சாம்பல் தூவவும்.',
    organicControlTe: 'గోమూత్రం మరియు అల్లం వెల్లుల్లి కషాయం పిచికారీ చేయండి. బూడిదను చల్లండి.',
    chemicalControl: 'Seed treatment with approved fungicide (e.g. Tricyclazole or Carbendazim). On field onset: Spray Tricyclazole or Isoprothiolane or Kasugamycin. For neck blast, protective spray at 5% panicle emergence is essential. Note: Check container label for registration, recommended water volume and pre-harvest interval; consult local KVK.',
    chemicalControlKn: 'ಬೀಜೋಪಚಾರಕ್ಕೆ ಟ್ರೈಸೈಕ್ಲಾಜೋಲ್ ಅಥವಾ ಕಾರ್ಬೆಂಡಾಜಿಮ್ ಬಳಸಿ. ರೋಗ ಲಕ್ಷಣ ಕಂಡಾಗ ಟ್ರೈಸೈಕ್ಲಾಜೋಲ್ ಅಥವಾ ಐಸೊಪ್ರೊಥಿಯೋಲೇನ್ ಸಿಂಪಡಿಸಿ. ಕಡ್ಡಾಯವಾಗಿ ಬಾಟಲಿ ಲೇಬಲ್ ಅನುಸರಿಸಿ.',
    chemicalControlTa: 'டிரைசைக்ளசோல் அல்லது ஐசோப்ரோதியோலேன் தெளிக்கவும். கதிர் வெளிவரும் போது முன்கூட்டியே தெளிப்பது அவசியம்.',
    chemicalControlTe: 'ట్రైసైక్లాజోల్ లేదా ఐసోప్రోథియోలేన్ పిచికారీ చేయండి. వెన్ను బయటకు వచ్చే సమయంలో ముందస్తు పిచికారీ ముఖ్యం.',
