    organicControlTe: 'దీపపు బుట్టలు అమర్చండి. వేప నూనెను మొదళ్లకు పిచికారీ చేయండి.',
    chemicalControl: 'When ETL is crossed (10-15 hoppers per hill): Spray Pymetrozine or Triflumezopyrim or Dinotefuran targeted strictly at the base of tillers. Avoid spraying top canopy. Note: Check container label for registration, recommended water volume and pre-harvest interval; consult local KVK.',
