    symptomsTa: 'இலை நுனி அல்லது விளிம்பில் நீர் நனைந்த புள்ளிகள் தோன்றி, அலை அலையான மஞ்சள் வெள்ளை பட்டைகளாக மாறும். காலையில் பால் போன்ற பாக்டீரியா கசிவு காணப்படும்.',
    symptomsTe: 'ఆకు చివర్లు లేదా అంచుల వద్ద నీటి మచ్చలు మొదలై, అలల వంటి పసుపు-తెలుపు చారలుగా మారతాయి. ఉదయాన్నే ఆకులపై జిగురు లాంటి బిందువులు కనిపిస్తాయి.',
    cause: 'Bacterium Xanthomonas oryzae invading hydathodes or wounds caused by storms.',
