    symptomsKn: 'ಎಳೆ ಎಲೆಗಳಲ್ಲಿ ರಂಧ್ರಗಳು ಮತ್ತು ಹರಿದ ಗುರುತುಗಳು ಕಾಣುತ್ತವೆ. ಸುಳಿಯೊಳಗೆ ಹೊಕ್ಕು ಮರದ ಪುಡಿಯಂತಹ ಮಲವನ್ನು ಶೇಖರಿಸಿ ಸುಳಿಯನ್ನು ಸಂಪೂರ್ಣ ನಾಶಮಾಡುತ್ತದೆ.',
    symptomsTa: 'இளம் இலைகளில் சிறு துளைகள் மற்றும் கிழிந்த விளிம்புகள் தோன்றும். சுருள் இலையினுள் மரத்தூள் போன்ற கழிவுகள் தேங்கி புழு உள்ளே மறைந்திருக்கும்.',
    symptomsTe: 'లేత ఆకులపై రంధ్రాలు పడతాయి. మొక్క సుడిలో దూరుతూ రంపపు పొట్టు లాంటి మలాన్ని విసర్జించి సుడిని నాశనం చేస్తుంది.',
    cause: 'Invasive noctuid moth larvae voraciously feeding inside whorl leaf bases.',
    favourableConditions: 'Warm dry spells followed by intermittent showers, continuous staggered plantings of maize in neighboring plots.',
    favourableHumidity: '60-80%',
