    affectedStages: ['Seedling', 'Vegetative Growth', 'Flowering'],
    spreadPattern: 'Strong flying adult moths cover tens of kilometers; female lays 1000+ eggs in masses covered in buff scales.',
    culturalControl: 'Synchronized community sowing across 10-15 days. Deep summer ploughing to expose pupae to predatory birds. Intercrop with cowpea or pigeonpea (2:1 or 4:1 ratio).',
    culturalControlKn: 'ಊರಿನ ಎಲ್ಲಾ ರೈತರು 10-15 ದಿನಗಳಲ್ಲಿ ಒಟ್ಟಿಗೆ ಬಿತ್ತನೆ ಮುಗಿಸಿ. ಅಲಸಂದಿ ಅಥವಾ ತೊಗರಿಯನ್ನು ಮಿಶ್ರಬೆಳೆಯಾಗಿ ಬೆಳೆಯಿರಿ.',
    culturalControlTa: 'ஒரே நேரத்தில் 10-15 நாட்களுக்குள் விதைப்பை முடிக்கவும். தட்டைப்பயறு ஊடுபயிராக பயிரிடவும்.',
    culturalControlTe: 'రైతులంతా ఒకేసారి 10-15 రోజుల్లో విత్తడం పూర్తి చేయండి. అలసంద అంతరపంటగా వేయండి.',
    biologicalControl: 'Release egg parasitoid Trichogramma pretiosum or Telenomus remus. Apply entomopathogenic fungal spray Metarhizium rileyi or Beauveria bassiana directly into whorls.',
    biologicalControlKn: 'ಟ್ರೈಕೋಗ್ರಾಮಾ ಪರಾವಲಂಬಿ ಬಳಸಿ. ಮೆಟಾರೈಜಿಯಮ್ ಅಥವಾ ಬ್ಯೂವೇರಿಯಾ ಜೈವಿಕ ಶಿಲೀಂಧ್ರವನ್ನು ಸಂಜೆ ವೇಳೆಯಲ್ಲಿ ಸುಳಿಯೊಳಗೆ ಸಿಂಪಡಿಸಿ.',
    biologicalControlTa: 'டிரைக்கோகிரம்மா ஒட்டுண்ணி விடவும். மெட்டாரைசியம் அல்லது பவேரியா பூஞ்சாணத்தை மாலையில் சுருளில் தெளிக்கவும்.',
