    organicControl: 'Drop a pinch of dry sand mixed with wood ash or neem cake directly into whorl funnels to mechanically kill young larvae. Install 4 pheromone traps per acre.',
    organicControlKn: 'ಒಣ ಮರಳು ಮತ್ತು ಬೂದಿ ಅಥವಾ ಬೇವಿನ ಹಿಂಡಿ ಮಿಶ್ರಣವನ್ನು ಚಿಟಿಕೆಯಷ್ಟು ಸುಳಿಯೊಳಗೆ ಹಾಕಿ. ಎಕರೆಗೆ 4 ಮೋಹಕ ಬಲೆ ಇಡಿ.',
    organicControlTa: 'சாம்பல் அல்லது வேப்பம்பிண்ணாக்கு கலந்த மணலை சுருள் இலையில் போடவும். 4 இனக்கவர்ச்சி பொறி வைக்கவும்.',
