    chemicalControl: 'When ETL is exceeded (>5-10% damaged whorls in early stage): Direct-spray Emamectin Benzoate or Spinetoram or Chlorantraniliprole straight into the central whorl cup with nozzle cap removed. Note: Consult local KVK; strictly follow label dosage and pre-harvest interval.',
