    symptomsKn: 'ಎಲೆಗಳ ಮೇಲೆ ಕದಿರು ಆಕಾರದ ಬೂದಿ ಕಲೆಗಳು. ತೆನೆಯ ಕುತ್ತಿಗೆ ಕಪ್ಪಾಗಿ ಮುರಿಯುವುದು (ಕುತ್ತಿಗೆ ಬೆಂಕಿ ರೋಗ). ರಾಗಿ ತೆನೆಯ ಬೆರಳುಗಳು ಕಪ್ಪಾಗಿ ಸುಟ್ಟಂತಾಗಿ ಕಾಳು ಕಟ್ಟುವುದಿಲ್ಲ (ಬೆರಳು ಬೆಂಕಿ ರೋಗ).',
    symptomsTa: 'இலைகளில் கண் வடிவ புள்ளிகள் தோன்றும். கதிர் கழுத்துப் பகுதி கருப்பாகி ஒடியும். விரல் போன்ற கதிர் பகுதிகள் கருப்பாகி பதராகும்.',
    symptomsTe: 'ఆకులపై కంటి ఆకారపు మచ్చలు. వెన్ను మెడ నల్లబడి విరిగిపోతుంది. రాగి వెన్ను వేళ్లు నల్లబడి గింజలు ఏర్పడవు.',
    cause: 'Fungus Pyricularia grisea attacking all aerial parts of Eleusine coracana.',
