    symptomsKn: 'ಎಲೆಗಳ ಮೇಲ್ಭಾಗದಲ್ಲಿ ಹಳದಿ ಅಂಚಿನ ಕಂದು-ಕಪ್ಪು ಚುಕ್ಕೆಗಳು ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತವೆ. ರೋಗ ತೀವ್ರವಾದಾಗ ಎಲ್ಲಾ ಎಲೆಗಳು ಹಳದಿಯಾಗಿ ಉದುರಿ ಕೇವಲ ಕಡ್ಡಿಗಳು ಉಳಿಯುತ್ತವೆ.',
