    type: 'fungal',
    severity: 'high',
    symptoms: 'Concentric dark brown to black rings resembling a "target board" or bullseye on older lower leaves, surrounded by yellow tissue. Stems develop dark sunken cankers; fruit shows dark leathery sunken lesions near the stem end.',
    symptomsKn: 'ಕೆಳಗಿನ ಹಳೆಯ ಎಲೆಗಳ ಮೇಲೆ ಗುರಿ ಹಲಗೆಯಂತಹ (ಟಾರ್ಗೆಟ್ ಬೋರ್ಡ್) ವೃತ್ತಾಕಾರದ ಕಂದು-ಕಪ್ಪು ಚುಕ್ಕೆಗಳು ಕಾಣಿಸಿಕೊಂಡು ಎಲೆ ಹಳದಿಯಾಗಿ ಉದುರುತ್ತದೆ. ಹಣ್ಣಿನ ತೊಟ್ಟಿನ ಬಳಿ ಕಪ್ಪು ಚರ್ಮದಂತಹ ಕಲೆಗಳು ಉಂಟಾಗುತ್ತವೆ.',
    symptomsTa: 'கீழ் இலைகளில் இலக்கு பலகை (Target board) போன்ற வட்ட வளைய புள்ளிகள் தோன்றும். இலைகள் மஞ்சள் நிறமாகி உதிர்ந்து விடும். பழத்தின் காம்பு பகுதியில் கருப்பு அழுகல் ஏற்படும்.',
    symptomsTe: 'కింది ముదిరిన ఆకులపై వలయాల వంటి (టార్గెట్ బోర్డు) నల్లటి మచ్చలు ఏర్పడతాయి. ఆకులు పసుపు రంగులోకి మారి రాలిపోతాయి. కాయల తొడిమ వద్ద నల్లటి మచ్చలు వస్తాయి.',
    cause: 'Fungus Alternaria solani surviving in soil debris and nightshade weeds.',
    favourableConditions: 'Warm temperatures (24-29°C), alternating wet and dry weather, heavy dew and nutrient-deficient or stressed plants.',
    favourableHumidity: '>80%',
    favourableTemp: '24-29°C',
    favourableSeasons: ['Kharif', 'Rabi', 'Zaid'],
    affectedStages: ['Vegetative Growth', 'Flowering', 'Fruiting'],
    spreadPattern: 'Spreads by wind, splashing rain, and mechanical contact on farm implements.',
