    culturalControlTa: 'மண்ணில் படும் அடி இலைகளை கவாத்து செய்யவும். நிலப்போர்வை அமைக்கவும். குச்சி நட்டு செடிகளை கட்டவும்.',
    culturalControlTe: 'నేలకు తగిలే కింది ఆకులను కత్తిరించండి. మల్చింగ్ చేయండి. కర్రలు కట్టి మొక్కలను పైకి లేపండి.',
