    biologicalControlKn: 'ಟ್ರೈಕೋಡರ್ಮಾ ಅಥವಾ ಸ್ಯೂಡೋಮೊನಾಸ್ ಜೈವಿಕ ದ್ರಾವಣ ಸಿಂಪಡಿಸಿ.',
    biologicalControlTa: 'டிரைக்கோடெர்மா அல்லது சூடோமோனாஸ் தெளிக்கவும்.',
