    symptoms: 'Large, irregular water-soaked pale green or dark brown lesions on leaves that expand with alarming speed; delicate white cottony or downy mildew growth on the underside of infected leaves in cool humid conditions; fruit develops firm, large, greasy, dark brown blotches that rapidly rot.',
    symptomsKn: 'ಎಲೆಗಳ ಮೇಲೆ ನೀರಿನಿಂದ ತೊಯ್ದಂತಹ ಕಪ್ಪು ಕಲೆಗಳು ವೇಗವಾಗಿ ಹರಡುತ್ತವೆ. ಎಲೆಯ ತಳಭಾಗದಲ್ಲಿ ಬಿಳಿ ಬೂಸ್ಟು ಪದರ ಕಾಣುತ್ತದೆ. ಹಣ್ಣುಗಳ ಮೇಲೆ ಕಂದು ಬಣ್ಣದ ಗಟ್ಟಿಯಾದ ಕೊಳೆತ ಕಲೆಗಳು ಉಂಟಾಗಿ ಇಡೀ ಗಿಡ ಸುಟ್ಟುಹೋದಂತಾಗುತ್ತದೆ.',
    symptomsTa: 'இலைகளில் நீர் நனைந்த பெரிய பழுப்பு புள்ளிகள் தோன்றி விரைவாக பரவும். இலைக்கு அடியில் பஞ்சு போன்ற வெள்ளை பூசணம் வளரும். காய்கள் அழுகிப் போகும்.',
    symptomsTe: 'ఆకులపై పెద్ద నీటి మచ్చలు ఏర్పడి వేగంగా వ్యాపిస్తాయి. ఆకు వెనుక భాగంలో తెల్లటి బూజు వస్తుంది. కాయలు కుళ్ళిపోతాయి.',
    cause: 'Oomycete pathogen Phytophthora infestans triggered by cold wet monsoon/winter spells.',
    favourableConditions: 'Cool temperatures (15-21°C), relative humidity >90%, persistent drizzle, dense fog, and continuous cloudy skies.',
