    culturalControlTa: 'வயல் நீரை வடிக்கவும். தெளிப்பு பாசனத்தை தவிர்க்கவும். பாதிக்கப்பட்ட செடிகளை உடனே எரிக்கவும்.',
    culturalControlTe: 'పొలంలో నీరు నిల్వకుండా చూడండి. స్ప్రింక్లర్ల వాడకం ఆపండి. తెగులు సోకిన మొక్కలను కాల్చండి.',
    biologicalControl: 'Preventive foliar application of Trichoderma viride or Bacillus subtilis formulations before the cold rainy spell.',
