    chemicalControlKn: 'ಮಳೆ ಬರುವ ಮುನ್ನ ಮುಂಜಾಗ್ರತೆಯಾಗಿ ಮ್ಯಾಂಕೋಜೆಬ್ ಸಿಂಪಡಿಸಿ. ರೋಗ ಕಂಡ ತಕ್ಷಣ ಸೈಮೊಕ್ಸಾನಿಲ್ + ಮ್ಯಾಂಕೋಜೆಬ್ ಅಥವಾ ಡೈಮೆಥೊಮಾರ್ಫ್ ಸಿಂಪಡಿಸಿ. ಲೇಬಲ್ ಸೂಚನೆ ಪಾಲಿಸಿ.',
