    type: 'bacterial',
    severity: 'critical',
    symptoms: 'Rapid, sudden wilting of the whole plant during sunny hours while leaves remain green (green wilt); vascular bundles turn brown; when an infected stem cut is suspended in clear water, milky white bacterial streaming streams out.',
    symptomsKn: 'ಗಿಡವು ಎಲೆಗಳು ಹಸಿರಾಗಿರುವಾಗಲೇ ಹಗಲೊತ್ತಿನಲ್ಲಿ ಹಠಾತ್ತನೆ ಬಾಡಿ ಸೊರಗುತ್ತದೆ. ಕಾಂಡದ ಒಳಭಾಗ ಕಂದು ಬಣ್ಣಕ್ಕೆ ತಿರುಗುತ್ತದೆ. ಕತ್ತರಿಸಿದ ಕಾಂಡವನ್ನು ಗಾಜಿನ ಲೋಟದ ನೀರಿನಲ್ಲಿ ಇಟ್ಟರೆ ಬಿಳಿ ಹಾಲಿನಂತಹ ದ್ರವ ಇಳಿಯುತ್ತದೆ.',
    symptomsTa: 'செடி இலைகள் பச்சையாக இருக்கும் போதே திடீரென வாடிவிடும். தண்டின் உட்சுவர் பழுப்பு நிறமாகும். வெட்டிய தண்டை தண்ணீரில் வைத்தால் பால் போன்ற பாக்டீரியா கசிவு வழியும்.',
    symptomsTe: 'ఆకులు పచ్చగా ఉన్నప్పుడే మొక్క అకస్మాత్తుగా వాడిపోతుంది. కాండం లోపల గోధుమ రంగులోకి మారుతుంది. కాండాన్ని నీటి గ్లాసులో ముంచితే పాల వంటి దారాలు కారుతాయి.',
    cause: 'Soil-borne bacterium Ralstonia solanacearum invading roots through wounds or nematodes.',
    favourableConditions: 'High soil moisture, warm temperatures (28-35°C), poorly drained soils, and presence of root-knot nematodes.',
    favourableHumidity: '>85%',
    favourableTemp: '28-35°C',
    favourableSeasons: ['Kharif', 'Zaid'],
    affectedStages: ['Vegetative Growth', 'Flowering', 'Fruiting'],
    spreadPattern: 'Moves through irrigation water, contaminated tillage implements, and infected seedlings.',
    culturalControl: 'Plant resistant rootstocks or varieties (e.g. Arka Ananya, Arka Abha from IIHR). Practice 3-year crop rotation with non-solanaceous crops like maize or marigold. Solarize nursery beds.',
    culturalControlKn: 'ಅರ್ಕಾ ಆನನ್ಯ ಅಥವಾ ಅರ್ಕಾ ಆಭಾದಂತಹ ನಿರೋಧಕ ತಳಿಗಳನ್ನು ಬೆಳೆಯಿರಿ. ಮೆಕ್ಕೆಜೋಳ ಅಥವಾ ಚೆಂಡುಹೂವಿನ ಜೊತೆ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡಿ. ಬೇಸಿಗೆಯಲ್ಲಿ ಮಣ್ಣಿನ ಸೌರೀಕರಣ ಮಾಡಿ.',
    culturalControlTa: 'அர்கா அனன்யா போன்ற எதிர்ப்பு ரகங்களை பயிரிடவும். மக்காச்சோளம் அல்லது செண்டுமல்லியுடன் 3 ஆண்டுகள் பயிர் சுழற்சி செய்யவும்.',
    culturalControlTe: 'అర్కా అనన్య వంటి నిరోధక రకాలను ఎంచుకోండి. మొక్కజొన్న లేదా బంతిపూలతో పంట మార్పిడి చేయండి.',
    biologicalControl: 'Soil drenching and seedling root dip with Pseudomonas fluorescens or Bacillus subtilis enriched in neem cake.',
