    chemicalControlTe: 'ఎండిన మొక్కను బతికించడం సాధ్యం కాదు. పక్క మొక్కల మొదళ్లలో కాపర్ ఆక్సిక్లోరైడ్ ద్రావణం పోయండి.',
    preventionSteps: ['Always perform water-glass bacterial streaming test to confirm.', 'Do not cultivate flooded fields with history of wilt.', 'Graft onto resistant eggplant rootstocks.'],
    preventionStepsKn: ['ಗಾಜಿನ ಲೋಟದಲ್ಲಿ ಕಾಂಡವನ್ನಿಟ್ಟು ಬ್ಯಾಕ್ಟೀರಿಯಾ ಪರೀಕ್ಷೆ ಮಾಡಿ ದೃಢಪಡಿಸಿ.', 'ಹಿಂದೆ ರೋಗ ಬಂದ ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ನೋಡಿಕೊಳ್ಳಿ.'],
    preventionStepsTa: ['கண்ணாடி டம்ளர் நீரில் தண்டை வைத்து பாக்டீரியா பரிசோதனை செய்யவும்.', 'நீர் தேங்காமல் பார்த்துக் கொள்ளவும்.'],
