    ipmStepsTa: ['படி 1: எதிர்ப்பு ரகம்', 'படி 2: நர்சரி சூரியஒளி பதப்படுத்துதல்', 'படி 3: வேர் நனைத்தல்', 'படி 4: பாதிக்கப்பட்ட இடத்தில் சுண்ணாம்பு இடுதல்'],
