    organicControlTa: 'மொட்டு பருவத்தில் வேப்பங்கொட்டை கரைசல் (5%) தெளிக்கவும்.',
    organicControlTe: 'మొగ్గ దశలో వేప గింజల కషాయం (5%) పిచಿಕారీ చేయండి.',
    chemicalControl: 'When ETL is crossed (8 moths/trap/day for 3 consecutive days or 10% rosette flowers): Spray Chlorantraniliprole or Emamectin Benzoate or Profenofos or Indoxacarb. Note: Read container label for dilution and pre-harvest interval; consult local KVK.',
    chemicalControlKn: 'ಹಾನಿ ಮಟ್ಟ ಮೀರಿದಾಗ ತಜ್ಞರ ಸಲಹೆಯಂತೆ ಕ್ಲೋರಾಂಟ್ರಾನಿಲಿಪ್ರೋಲ್ ಅಥವಾ ಇಮಾಮೆಕ್ಟಿನ್ ಬೆಂಜೊಯೆಟ್ ಸಿಂಪಡಿಸಿ. ಲೇಬಲ್ ಸೂಚನೆ ಪಾಲಿಸಿ.',
