    nameTa: 'கொண்டைக்கடலை வாடல் நோய்',
    nameTe: 'శనగ ఎండు తెగులు',
    scientificName: 'Fusarium oxysporum f. sp. ciceris',
    type: 'fungal',
    severity: 'critical',
    symptoms: 'Drooping of upper petioles and leaves; foliage turns dull green or greyish-green followed by yellowing and desiccation; internal xylem vessels show deep blackish-brown discoloration when stem is split vertically.',
    symptomsKn: 'ಗಿಡದ ಮೇಲ್ಭಾಗದ ರೆಂಬೆ ಎಲೆಗಳು ಬಾಗಿ ತೂಗಾಡುತ್ತವೆ. ನಂತರ ಎಲೆಗಳು ಬೂದು-ಹಸಿರಾಗಿ ಕ್ರಮೇಣ ಒಣಗುತ್ತವೆ. ಕಾಂಡವನ್ನು ಉದ್ದಕ್ಕೆ ಸೀಳಿದರೆ ಒಳಗಿನ ನರಗಳು ಕಪ್ಪಾಗಿ ಕೊಳೆತಿರುವುದು ಕಾಣುತ್ತದೆ.',
    symptomsTa: 'செடியின் மேல் இலைகள் வாடி தொங்கும். இலைகள் சாம்பல்-பச்சை நிறமாகி பின்னர் காய்ந்து விடும். தண்டின் உள்பகுதி பழுப்பு-கருப்பு நிறமாக மாறும்.',
    symptomsTe: 'మొక్క పై కొమ్మలు, ఆకులు వాలిపోతాయి. ఆకులు పాలిపోయిన ఆకుపచ్చ రంగులోకి మారి ఎండిపోతాయి. కాండాన్ని నిలువుగా చీల్చితే లోపలి నాళాలు నల్లగా మారడం కనిపిస్తుంది.',
    cause: 'Soil-borne and seed-borne fungus Fusarium oxysporum f. sp. ciceris.',
    favourableConditions: 'High soil temperatures (25-30°C) during seedling or pod-filling stages, dry soil conditions, and repeated chickpea cropping.',
    favourableHumidity: '50-70%',
    favourableTemp: '25-30°C',
    favourableSeasons: ['Rabi'],
    affectedStages: ['Seedling', 'Vegetative Growth', 'Flowering', 'Fruiting'],
    spreadPattern: 'Spreads through infected soil and seed; chlamydospores survive in soil for over 6 years.',
    culturalControl: 'Sow resistant varieties like JG-11, JAKI-9218, or Annigeri-1 (UAS Dharwad). Deep summer ploughing to expose fungal spores to hot sun. Practice 3-year crop rotation with sorghum or wheat.',
    culturalControlKn: 'ಜೆಜಿ-11 ಅಥವಾ ಜಾಕಿ-9218 ರಂತಹ ನಿರೋಧಕ ತಳಿಗಳನ್ನು ಬೆಳೆಯಿರಿ. ಬೇಸಿಗೆಯಲ್ಲಿ ಆಳವಾಗಿ ಉಳುಮೆ ಮಾಡಿ. ಜೋಳ ಅಥವಾ ಗೋಧಿಯೊಂದಿಗೆ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡಿ.',
    culturalControlTa: 'ஜேஜி-11 போன்ற எதிர்ப்பு ரகங்களை பயிரிடவும். கோடை உழவு செய்யவும். சோளம் அல்லது கோதுமையுடன் பயிர் சுழற்சி செய்யவும்.',
    culturalControlTe: 'JG-11 లేదా JAKI-9218 వంటి నిరోధక రకాలను వాడండి. వేసవి దుక్కులు చేయండి. జొన్న లేదా గోధుమలతో పంట మార్పిడి చేయండి.',
    biologicalControl: 'Seed treatment with Trichoderma viride or Pseudomonas fluorescens enriched in well-decomposed FYM applied to soil.',
    biologicalControlKn: 'ಟ್ರೈಕೋಡರ್ಮಾ ಅಥವಾ ಸ್ಯೂಡೋಮೊನಾಸ್‌ನಿಂದ ಬೀಜೋಪಚಾರ ಮಾಡಿ ಮತ್ತು ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರದೊಂದಿಗೆ ಮಣ್ಣಿಗೆ ಹಾಕಿ.',
    biologicalControlTa: 'டிரைக்கோடெர்மா கொண்டு விதை நேர்த்தி செய்து தொழு உரத்துடன் நிலத்தில் இடவும்.',
    biologicalControlTe: 'ట్రైకోడెర్మాతో విత్తన శుద్ధి చేయండి మరియు పశువుల ఎరువుతో కలిపి నేలలో వేయండి.',
    organicControl: 'Apply neem cake (150-200 kg/acre) during land preparation to suppress soil-borne fungal inoculum.',
    organicControlKn: 'ಜಮೀನು ಹದಮಾಡುವಾಗ ಎಕರೆಗೆ 150-200 ಕೆಜಿ ಬೇವಿನ ಹಿಂಡಿ ಹಾಕಿ.',
    organicControlTa: 'நிலம் தயாரிக்கும் போது ஏக்கருக்கு 150-200 கிலோ வேப்பம்பிண்ணாக்கு இடவும்.',
