    chemicalControl: 'Seed treatment with Carbendazim + Thiram or Carboxin + Thiram before sowing. Note: Post-infection chemical sprays are completely ineffective against vascular wilt; prevention through seed treatment is mandatory. Consult local KVK.',
    chemicalControlKn: 'ಬಿತ್ತನೆ ಮುನ್ನ ಕಾರ್ಬೆಂಡಾಜಿಮ್ + ಥೈರಮ್‌ನಿಂದ ಕಡ್ಡಾಯವಾಗಿ ಬೀಜೋಪಚಾರ ಮಾಡಿ. ಗಿಡ ಸೊರಗಿದ ನಂತರ ಯಾವುದೇ ಸಿಂಪಡಣೆ ಕೆಲಸ ಮಾಡುವುದಿಲ್ಲ.',
    chemicalControlTa: 'கட்டாய விதை நேர்த்தி செய்யவும். வாடிய பிறகு தெளிக்கும் மருந்துகள் பயனளிக்காது.',
    chemicalControlTe: 'విత్తే ముందు కార్బెంజెడిమ్ + థైరమ్‌తో తప్పనిసరిగా విత్తన శుద్ధి చేయండి. తెగులు సోకాక స్ప్రేలు పనిచేయవు.',
    preventionSteps: ['Always treat seeds with bio-agent or fungicide.', 'Never plant in fields with severe wilt history.', 'Delay sowing slightly if temperatures are unusually high in October.'],
    preventionStepsKn: ['ಕಡ್ಡಾಯವಾಗಿ ಬೀಜೋಪಚಾರ ಮಾಡಿ.', 'ಹಿಂದೆ ರೋಗ ಬಂದ ಜಮೀನಿನಲ್ಲಿ ಸತತವಾಗಿ ಕಡಲೆ ಬೆಳೆಯಬೇಡಿ.'],
    preventionStepsTa: ['கட்டாய விதை நேர்த்தி செய்யவும்.', 'தொடர்ந்து கொண்டைக்கடலை பயிரிட வேண்டாம்.'],
