    organicControlTa: 'பூக்கும் தருணத்தில் வேப்பங்கொட்டை கரைசல் (5%) தெளிக்கவும்.',
    organicControlTe: 'పూత దశలో వేప గింజల కషాయం (5%) పిచಿಕారీ చేయండి.',
    chemicalControl: 'When ETL is crossed (1 larva per meter row or 5-10% damaged pods): Foliar spray of Chlorantraniliprole or Emamectin Benzoate or Indoxacarb. Note: Strictly observe registered container label dosage, water volume, and pre-harvest interval; consult local KVK.',
    chemicalControlKn: 'ಒಂದು ಮೀಟರ್ ಸಾಲಿನಲ್ಲಿ 1 ಹುಳು ಕಂಡಾಗ ಕ್ಲೋರಾಂಟ್ರಾನಿಲಿಪ್ರೋಲ್ ಅಥವಾ ಇಮಾಮೆಕ್ಟಿನ್ ಬೆಂಜೊಯೆಟ್ ಸಿಂಪಡಿಸಿ. ಲೇಬಲ್ ಸೂಚನೆ ಪಾಲಿಸಿ.',
