    scientificName: 'Chilo infuscatellus',
    type: 'insect_pest',
    severity: 'critical',
    symptoms: 'Drying of the central whorl shoot causing a typical "Dead Heart" in young cane crops (1 to 3 months old); the dried shoot can be pulled out easily with an unpleasant rotting odor at the base; entry pinholes visible at ground level on the shoot.',
    symptomsKn: '1 ರಿಂದ 3 ತಿಂಗಳ ಕಬ್ಬಿನ ಬೆಳೆಯ ಸುಳಿ ಒಣಗುತ್ತದೆ (ಡೆಡ್ ಹಾರ್ಟ್). ಒಣಗಿದ ಸುಳಿಯನ್ನು ಎಳೆದರೆ ಸುಲಭವಾಗಿ ಕೊಳೆತ ದುರ್ವಾಸನೆಯೊಂದಿಗೆ ಕಿತ್ತು ಬರುತ್ತದೆ. ಮಣ್ಣಿನ ಮಟ್ಟದಲ್ಲಿ ರಂಧ್ರವಿರುತ್ತದೆ.',
    symptomsTa: '1 முதல் 3 மாத இளம் கரும்பில் நடுக்குருத்து காய்ந்து விடும் (Dead Heart). இழுத்தால் துர்நாற்றத்துடன் எளிதில் வந்துவிடும். தரைமட்டத்தில் துளைகள் காணப்படும்.',
    symptomsTe: '1 నుండి 3 నెలల లేత చెరకులో సుడి ఎండిపోతుంది ("డెడ్ హార్ట్"). ఎండిన సుడిని లాగితే కుళ్ళిన వాసనతో తేలికగా వచ్చేస్తుంది. నేల మట్టంలో రంధ్రం ఉంటుంది.',
    cause: 'Larvae of Chilo infuscatellus boring into shoot bases near the soil surface.',
    favourableConditions: 'Hot dry weather conditions (35-40°C), low relative humidity, light sandy soils, and late planting during peak summer.',
