    favourableTemp: '32-40°C',
    favourableSeasons: ['Zaid', 'Kharif'],
    affectedStages: ['Tillering', 'Vegetative Growth'],
    spreadPattern: 'Moths lay flat scale-like egg masses on lower leaf surfaces; young caterpillars crawl to soil surface and bore into young shoots.',
    culturalControl: 'Plant early (before March). Trash mulching (spreading cane trash 10 cm thick along furrows) to conserve soil moisture and lower soil surface temperature. Earthing up at 45-60 days to bury root shoot bases.',
    culturalControlKn: 'ಮಾರ್ಚ್ ಒಳಗೆ ಮುಂಚಿತವಾಗಿ ನಾಟಿ ಮಾಡಿ. ಸಾಲುಗಳ ನಡುವೆ ಕಬ್ಬಿನ ರವದಿಯನ್ನು (10 ಸೆಂ.ಮೀ ದಪ್ಪ) ಹೊದಿಕೆಯಾಗಿ ಹಾಕಿ. 45-60 ದಿನಗಳಲ್ಲಿ ಮಣ್ಣು ಏರಿಸಿ.',
