    culturalControlTe: 'మార్చి కంటే ముందే నాట్లు వేయండి. చెరకు చెత్తను సాళ్లలో మల్చింగ్‌గా వేయండి. 45-60 రోజుల్లో మట్టిని ఎగదోయండి.',
    biologicalControl: 'Release egg parasitoid Trichogramma chilonis cards (20,000 eggs/acre) at weekly intervals from 30 days after planting. Spray granulosis virus (Chilo GV) formulation.',
    biologicalControlKn: 'ನಾಟಿ ಮಾಡಿದ 30 ದಿನಗಳಿಂದ ವಾರಕ್ಕೊಮ್ಮೆ ಟ್ರೈಕೋಗ್ರಾಮಾ ಕಿಲೋನಿಸ್ ಕಾರ್ಡ್‌ಗಳನ್ನು ಅಳವಡಿಸಿ.',
    biologicalControlTa: 'டிரைக்கோகிரம்மா சிலோனிஸ் ஒட்டுண்ணி அட்டைகளை வாரம் ஒருமுறை கட்டவும்.',
