    ipmStepsKn: ['ಹಂತ 1: ಆರೋಗ್ಯಕರ ಬಿತ್ತನೆ ಕಬ್ಬು', 'ಹಂತ 2: ಕೆಂಪು ತುದಿಗಳ ತಿರಸ್ಕಾರ', 'ಹಂತ 3: ಜೈವಿಕ ತುಂಡು ಸಂಸ್ಕರಣೆ', 'ಹಂತ 4: ನೀರು ಬಸಿಯುವುದು', 'ಹಂತ 5: ರೋಗಪೀಡಿತ ಗಿಡ ಸುಡುವುದು'],
    ipmStepsTa: ['படி 1: சான்றளிக்கப்பட்ட கரணை', 'படி 2: சிவப்பு கரணை நீக்கம்', 'படி 3: கரணை நேர்த்தி', 'படி 4: வடிகால் வசதி', 'படி 5: பாதித்த தூர்களை அழித்தல்'],
    ipmStepsTe: ['దశ 1: ధృవీకరించిన విత్తనం', 'దశ 2: ఎర్ర ముక్కల ఏరివేత', 'దశ 3: విత్తన శుద్ధి', 'దశ 4: మురుగు నీటి పారుదల', 'దశ 5: తెగులు మొక్కల నాశనం'],
    safetyNotes: 'Burn and bury uprooted red-rot infected canes away from irrigation canals to prevent downstream contamination.',
