    symptomsKn: 'ಕೊಂಬೆಗಳು ತುದಿಯಿಂದ ಕೆಳಕ್ಕೆ ಒಣಗುತ್ತಾ ಬರುತ್ತವೆ (ಡೈ-ಬ್ಯಾಕ್). ಹಣ್ಣಾಗುವ ಮೆಣಸಿನಕಾಯಿಗಳ ಮೇಲೆ ವೃತ್ತಾಕಾರದ ತಗ್ಗು ಬಿದ್ದ ಕಪ್ಪು ಚುಕ್ಕೆಗಳು ಕಾಣಿಸಿಕೊಂಡು ಕಾಯಿ ಒಣಗಿ ಬಿಳಿ-ಹುಲ್ಲಿನ ಬಣ್ಣಕ್ಕೆ ತಿರುಗಿ ಉದುರುತ್ತವೆ.',
    symptomsTa: 'இளம் கிளைகள் நுனியிலிருந்து கீழ்நோக்கி காய்ந்து சாம்பல் நிறமாகும் (நுனிகருகல்). பழுக்கும் மிளகாயில் வட்ட வடிவ பள்ளமான கரும்புள்ளிகள் தோன்றி காய்கள் அழுகி உதிரும்.',
    symptomsTe: 'లేత కొమ్మలు పైనుండి కిందికి ఎండిపోతాయి (డై-బ్యాక్). పండు మిరపకాయలపై నల్లటి గుండ్రని మచ్చలు ఏర్పడి కాయలు ఎండి రాలిపోతాయి.',
    cause: 'Fungus Colletotrichum capsici carried on seed and splashing from infected plant residues.',
