    chemicalControl: 'For thrips: Foliar spray of Fipronil or Spinetoram or Acetamiprid; For mites: Foliar spray of Spiromesifen or Fenpyroximate or Wettable Sulfur. Note: Check container label carefully for registration, proper dilution and pre-harvest interval; consult local KVK.',
    chemicalControlKn: 'ಹೇನುಗಳಿಗೆ ಫಿಪ್ರೋನಿಲ್ ಅಥವಾ ಸ್ಪಿನೆಟೊರಾಮ್ ಸಿಂಪಡಿಸಿ; ನುಸಿಗಳಿಗೆ ಸ್ಪೈರೋಮೆಸಿಫೆನ್ ಅಥವಾ ಕರಗುವ ಗಂಧಕ ಸಿಂಪಡಿಸಿ. ಲೇಬಲ್ ಸೂಚನೆ ಪಾಲಿಸಿ.',
