    ipmStepsTa: ['படி 1: மேட்டுப்பாத்தி', 'படி 2: ஒட்டும் பொறி', 'படி 3: கழிவு நீக்கம்', 'படி 4: ஒட்டும் திரவத்துடன் தெளிப்பு'],
    ipmStepsTe: ['దశ 1: ఎత్తు మడులు', 'దశ 2: జిగురు బుట్టలు', 'దశ 3: వ్యర్థాల నాశనం', 'దశ 4: జిగురుతో శిలీంధ్రనాశిని పిచికారీ'],
