    scientificName: 'Fusarium oxysporum f. sp. cubense',
    type: 'fungal',
    severity: 'critical',
    symptoms: 'Yellowing of lower older leaves starting from leaf margins towards the midrib; petiole buckles at the pseudostem junction and dead leaves hang down skirts like a dry collar around the trunk; longitudinal splitting of pseudostem base; continuous brown to black vascular discoloration inside pseudostem and corm.',
    symptomsKn: 'ಕೆಳಗಿನ ಹಳೆಯ ಎಲೆಗಳು ಅಂಚಿನಿಂದ ಹಳದಿಯಾಗಿ ಒಣಗುತ್ತವೆ. ಎಲೆಯ ತೊಟ್ಟು ಮುರಿದು ಬಾಗಿ ಕಾಂಡದ ಸುತ್ತ ಒಣಗಿ ನೇತಾಡುತ್ತವೆ. ಕಾಂಡದ ಬುಡವು ಉದ್ದಕ್ಕೆ ಸೀಳುತ್ತದೆ. ಕಾಂಡ ಮತ್ತು ಗಡ್ಡೆಯನ್ನು ಸೀಳಿದರೆ ಒಳಗೆ ಕಂದು-ಕಪ್ಪು ಬಣ್ಣದ ರಕ್ತನಾಳಗಳ ಕಲೆಗಳು ಕಾಣುತ್ತವೆ.',
    symptomsTa: 'கீழ் இலைகள் மஞ்சளாகி தண்டின் சந்திப்பில் ஒடிந்து காய்ந்து தொங்கும் (Skirt effect). தண்டின் அடிப்பகுதி நீளவாக்கில் வெடிக்கும். கிழங்கை வெட்டிப் பார்த்தால் உள்பகுதி கருப்பாக அழுகியிருக்கும்.',
    symptomsTe: 'కింది ముదిరిన ఆకులు పసుపు రంగులోకి మారి కాండం వద్ద విరిగి వేలాడతాయి. కాండం మొదలు నిలువుగా పగులుతుంది. కాండం, దుంపను కోసి చూస్తే లోపల నల్లటి చారలు కనిపిస్తాయి.',
    cause: 'Soil-borne vascular fungus Fusarium oxysporum f. sp. cubense surviving for decades in soil.',
