    spreadPattern: 'Spreads through infected planting suckers, running irrigation water, and contaminated soil on implements.',
    culturalControl: 'Plant tissue-cultured disease-free plantlets or certified suckers. Plant resistant cultivars like Grand Naine (Cavendish group is resistant to Race 1). Dip suckers in bio-agent slurry. Drench and isolate infected pits with lime (1 kg/pit).',
    culturalControlKn: 'ಅಂಗಾಂಶ ಕೃಷಿ (ಟಿಶ್ಯೂ ಕಲ್ಚರ್) ಸಸಿಗಳನ್ನು ಬೆಳೆಯಿರಿ. ಕ್ಯಾವೆಂಡಿಷ್ (ಜಿ-9) ತಳಿ ಬೆಳೆಯಿರಿ. ರೋಗಪೀಡಿತ ಗುಂಡಿಗಳಿಗೆ 1 ಕೆಜಿ ಸುಣ್ಣ ಹಾಕಿ ಪ್ರತ್ಯೇಕಿಸಿ.',
