    culturalControlTe: 'టిష్యూ కల్చర్ మొక్కలను నాటండి. G-9 వంటి నిరోధక రకాలను ఎంచుకోండి. తెగులు సోకిన గుంతల్లో 1 కిలో సున్నం వేయండి.',
    biologicalControl: 'Apply Trichoderma viride or Pseudomonas fluorescens enriched in neem cake + FYM (25g each per sucker at planting).',
