    symptomsKn: 'ಹೂಗೊಂಚಲುಗಳು ಕಪ್ಪಾಗಿ ಸುಟ್ಟುಹೋದಂತಾಗಿ ಹೂಗಳು ಉದುರುತ್ತವೆ (ಬ್ಲಾಸಮ್ ಬ್ಲೈಟ್). ಎಲೆಗಳ ಮೇಲೆ ಕಂದು-ಕಪ್ಪು ಚುಕ್ಕೆಗಳು ಕಾಣುತ್ತವೆ. ಹಣ್ಣುಗಳ ಮೇಲೆ ತಗ್ಗು ಬಿದ್ದ ಕಪ್ಪು ಚುಕ್ಕೆಗಳು ಉಂಟಾಗಿ ತಿರುಳು ಕೊಳೆಯುತ್ತದೆ.',
    symptomsTa: 'பூங்கொத்துகள் கருகி உதிரும். இலைகளில் பழுப்பு-கருப்பு புள்ளிகள் தோன்றும். மாம்பழங்களின் மேல் வட்ட வடிவ கருப்பு அழுகல் புள்ளிகள் ஏற்பட்டு சதை அழுகும்.',
    symptomsTe: 'పూత నల్లబడి మాడిపోయి రాలిపోతుంది. ఆకులపై నల్లటి మచ్చలు వస్తాయి. కాయలపై నల్లటి గుండ్రని మచ్చలు ఏర్పడి గుజ్జు కుళ్ళిపోతుంది.',
    cause: 'Fungus Colletotrichum gloeosporioides overseasoning on old twigs and leaves.',
    favourableConditions: 'Heavy unseasonal rains or persistent fog/dew during flowering (November to February), temperatures 24-30°C, and relative humidity >85%.',
    favourableHumidity: '>85%',
    favourableTemp: '24-30°C',
    favourableSeasons: ['Rabi', 'Zaid'],
    affectedStages: ['Flowering', 'Fruiting', 'Harvesting'],
    spreadPattern: 'Rain splashes and dew drops carry conidia from old twigs down onto flower panicles and fruit shoulders.',
    culturalControl: 'Prune dead and dried twigs 10 cm below infection line after harvest and paste with Bordeaux paste. Clear ground litter and destroy fallen leaves. Maintain tree canopy aeration.',
    culturalControlKn: 'ಕೊಯ್ಲಿನ ನಂತರ ಒಣಗಿದ ಕೊಂಬೆಗಳನ್ನು ಕತ್ತರಿಸಿ ಬೋರ್ಡೋ ಪೇಸ್ಟ್ ಹಚ್ಚಿ. ತೋಟದ ನೆಲದಲ್ಲಿರುವ ಒಣ ಎಲೆಗಳನ್ನು ಗುಡಿಸಿ ನಾಶಮಾಡಿ.',
    culturalControlTa: 'அறுவடைக்கு பின் காய்ந்த கிளைகளை கவாத்து செய்து போர்டோ பசை பூசவும். கீழே விழுந்த இலைகளை எரிக்கவும்.',
    culturalControlTe: 'కోత తర్వాత ఎండిన కొమ్మలను కత్తిరించి బోర్డో పేస్ట్ పూయండి. రాలిన ఆకులను తీసి కాల్చండి.',
    biologicalControl: 'Foliar spray of Trichoderma viride or Pseudomonas fluorescens on flower panicles before bud opening.',
    biologicalControlKn: 'ಹೂ ಅರಳುವ ಮುನ್ನ ಟ್ರೈಕೋಡರ್ಮಾ ಅಥವಾ ಸ್ಯೂಡೋಮೊನಾಸ್ ದ್ರಾವಣ ಸಿಂಪಡಿಸಿ.',
    biologicalControlTa: 'பூக்கும் முன் டிரைக்கோடெர்மா அல்லது சூடோமோனாஸ் தெளிக்கவும்.',
    biologicalControlTe: 'పూత విచ్చుకోవడానికి ముందే ట్రైకోడెర్మా పిచికారీ చేయండి.',
    organicControl: 'Foliar spray of 1% Bordeaux mixture or Copper Hydroxide before flower emergence and after fruit set.',
    organicControlKn: 'ಹೂ ಬಿಡುವ ಮುನ್ನ ಮತ್ತು ಕಾಯಿ ಕಚ್ಚಿದ ನಂತರ 1% ಬೋರ್ಡೋ ದ್ರಾವಣ ಸಿಂಪಡಿಸಿ.',
    organicControlTa: '1% போர்டோ கலவை தெளிக்கவும்.',
    organicControlTe: '1% బోర్డో మిశ్రమం పిచికారీ చేయండి.',
    chemicalControl: 'Foliar spray of Carbendazim or Thiophanate Methyl or Azoxystrobin or Difenoconazole at panicle emergence, followed by second spray at pea-stage fruit set. Post-harvest hot water dip (52°C for 10 min) for fruits. Note: Check container label and pre-harvest interval; consult local KVK.',
    chemicalControlKn: 'ಹೂಗೊಂಚಲು ಬರುವಾಗ ಮತ್ತು ಕಡಲೆ ಗಾತ್ರದ ಕಾಯಿ ಕಟ್ಟುವಾಗ ಕಾರ್ಬೆಂಡಾಜಿಮ್ ಅಥವಾ ಅಜಾಕ್ಸಿಸ್ಟ್ರೋಬಿನ್ ಸಿಂಪಡಿಸಿ. ಕೊಯ್ಲಿನ ನಂತರ ಹಣ್ಣುಗಳನ್ನು ಬಿಸಿ ನೀರಿನಲ್ಲಿ ಅದ್ದಿ.',
    chemicalControlTa: 'பூங்கொத்து வரும் போது மற்றும் பட்டாணி அளவு காய் பிடிக்கும் போது கார்பென்டாசிம் தெளிக்கவும்.',
    chemicalControlTe: 'పూత దశలో మరియు కాయ దశలో కార్బెంజెడిమ్ లేదా అజాక్సిస్ట్రోబిన్ పిచికారీ చేయండి.',
    preventionSteps: ['Regular annual pruning of dead center twigs.', 'Prophylactic spray before flowering flush.', 'Post-harvest hot water fruit treatment.'],
    preventionStepsKn: ['ಪ್ರತಿ ವರ್ಷ ಒಣ ಕೊಂಬೆಗಳನ್ನು ಸವರುತ್ತಿರಿ.', 'ಹೂ ಬಿಡುವ ಮುನ್ನವೇ ಮುಂಜಾಗ್ರತಾ ಸಿಂಪರಣೆ ಮಾಡಿ.'],
    preventionStepsTa: ['ஆண்டுதோறும் கவாத்து செய்யவும்.', 'பூக்கும் முன் முன்கூட்டியே தெளிக்கவும்.'],
    preventionStepsTe: ['ప్రతి ఏటా ఎండిన కొమ్మలను కత్తిరించండి.', 'పూతకు ముందే పిచికారీ చేయండి.'],
