    ipmStepsKn: ['ಹಂತ 1: ತೋಟದ ನೈರ್ಮಲ್ಯ ಮತ್ತು ಕವಲೊಡೆಯುವಿಕೆ', 'ಹಂತ 2: ಬೋರ್ಡೋ ಪೇಸ್ಟ್ ಲೇಪನ', 'ಹಂತ 3: ಹೂ ಬಿಡುವ ಮುನ್ನ ತಾಮ್ರದ ಸಿಂಪರಣೆ', 'ಹಂತ 4: ಅಕಾಲಿಕ ಮಳೆಗೆ ಶಿಲೀಂಧ್ರನಾಶಕ'],
    ipmStepsTa: ['படி 1: கவாத்து மற்றும் சுகாதாரம்', 'படி 2: போர்டோ பசை பூசுதல்', 'படி 3: பூக்கும் முன் காப்பர் தெளிப்பு', 'படி 4: மழை வந்தால் பூஞ்சாணக்கொல்லி'],
    ipmStepsTe: ['దశ 1: కొమ్మల కత్తిరింపు', 'దశ 2: బోర్డో పేస్ట్ పూయడం', 'దశ 3: పూతకు ముందు కాపర్ పిచికారీ', 'దశ 4: అకాల వర్షాల్లో శిలీంధ్రనాశిని'],
